# Initially generated by GitHub Copilot.
"""
Preview a word on an Aleppo Codex page image.

Given a book name, a verse reference (c:v), and a Hebrew word, this
script:
1. Looks up the word in line-break data (page, col, line-num)
2. Gets pixel coordinates from column-coordinate data
3. Loads the page image from aleppo-pages/
4. Crops a generous region around the target line with a 2D fade overlay
5. Generates an HTML preview page in .novc/ and opens it

When line-break data is not available for the given book, falls back to
index-flat-annotated.json and reports the page ID only.

Usage:
    .venv/Scripts/python.exe py/main_ac_find_word_in_images.py [--wide] <book> <c:v> <word>

Examples:
    .venv/Scripts/python.exe py/main_ac_find_word_in_images.py Job 7:1 "וְכִימֵ֖֗י"
"""

import functools
import http.server
import json
import socket
import sys
import threading
import webbrowser

from PIL import Image, ImageDraw
from wlc_cmn.utf8_io import force_utf8_io

import ac_paths
from py_ac_word_image_helper.codex_page import (
    CC_DIR,
    LB_DIR,
    find_pages_for_verse,
    get_line_bbox,
    load_index,
    load_page_image,
)
from py_ac_word_image_helper.crop import compute_fade_overlay, estimate_word_position
from py_ac_word_image_helper.alef_bet_to_ascii import heb_alef_bet_to_ascii
from py_ac_word_image_helper.flat_index import find_pages_in_flat_index
