def main():
    # Parse optional --wide flag
    args = sys.argv[1:]
    wide = False
    if "--wide" in args:
        wide = True
        args.remove("--wide")

    if len(args) == 3:
        book = args[0]
        cv = args[1]
        word = args[2]
    else:
        print(
            "Usage: .venv/Scripts/python.exe py/main_ac_find_word_in_images.py"
            " [--wide] <book> <c:v> <word>"
        )
        print('Example: ... Job 7:1 "וְכִימֵי"')
        print("  --wide  Extend margins to capture masorah parva (Mp) notes")
        sys.exit(1)

    if ":" not in cv:
        print(f"ERROR: verse must be in c:v format (e.g. 7:1), got: {cv}")
        sys.exit(1)

    pages = load_index(book)
    if pages:
        result = find_and_preview(word, book, cv, pages, wide=wide)
        if result:
            generate_html(result)
        else:
            sys.exit(1)
    else:
        # Fallback: no line-break data for this book/region.
        # Report page ID(s) from the flat index.
        ch, v = (int(x) for x in cv.split(":"))
        fallback_pages = find_pages_in_flat_index(book, ch, v)
        if fallback_pages:
            print(f"\n=== {book} {cv}: {word} ===")
            print(f"  No line-break data available for {book}.")
            print(f"  Flat-index page lookup: {fallback_pages[0]}")
            if len(fallback_pages) > 1:
                print(f"  (also on: {', '.join(fallback_pages[1:])})")
        else:
            print(f"ERROR: {book} {cv} not found in flat index.")
            sys.exit(1)


if __name__ == "__main__":
    # This repo's convention, and here it replaces a module-scope
    # ``sys.stdout = io.TextIOWrapper(sys.stdout.buffer, ...)`` that ran on IMPORT
    # and did real damage: rewrapping the buffer abandons whatever the old wrapper
    # had buffered, so importing this module silently swallowed output another
    # program had already printed.  Phase 3 of
    # ``doc/PLAN-evacuate-python-from-codex-index-trio.md`` found it by watching a
    # smoke test lose its first eighteen lines the moment this module was imported.
    # ``force_utf8_io`` reconfigures the existing streams instead, and does it here
    # rather than at import, so nothing happens to a caller that only imports.
    force_utf8_io()
    main()
